/** Every module id, in teaching order. The validator and tests read this. */
export const CODEBASE_ENGINEERING_MODULE_IDS = CODEBASE_ENGINEERING_COURSE.months.flatMap((m) =>
  m.modules.map((mod) => mod.id)
);

export default CODEBASE_ENGINEERING_COURSE;
